namespace hanmo::resident {using namespace naval_repair_exact_detail;namespace naval_repair_exact_detail {
void validate_source_shape(const CommonStore& c,const NavalState& n,const MilitaryActionTimeState& s,const ExactNavalRepairSourceContext& x,const NewNavalRepairTimeSource2& f){
 const auto& t=f.timing;const auto& terms=f.original_terms;
 take(validate_naval_repair_policy(x.naval_catalog,x.access.common_catalog));
 if(x.naval_catalog.repair_charge_policy)take(validate_naval_repair_charge_policy(*x.naval_catalog.repair_charge_policy,x.naval_catalog,x.military_catalog,x.access.common_catalog));
 if(!allocated(t.action_ref,"action:")||f.rule_version!=2||!same_source(t.start_fact_ref,start_ref(t.action_ref))||t.elapsed_ref.action_ref!=t.action_ref||!naval_request_key_valid(f.request_key))fail("ExactNavalRepairSourceIdentityMismatch",t.action_ref);
 header(c,t.start_fact_ref);
 const auto now=take(x.clock.read_current_moment());if(take(compare_world_moments(t.started_at,now,x.budget))>0)fail("FutureExactNavalRepairSource",t.action_ref);
 for(const auto& old:n.repairs.starts)if(old.id==t.action_ref)fail("DuplicateLegacyExactNavalRepair",t.action_ref);
 for(const auto& old:n.repair_charges.charges)if(old.action_id==t.action_ref)fail("DuplicateLegacyExactNavalRepairCharge",t.action_ref);
 if(s.dynamic_action_facts.find(t.action_ref)||s.dynamic_logistics_facts.find(t.action_ref)||s.dynamic_training_facts.find(t.action_ref))fail("DuplicateExactMilitaryAction",t.action_ref);
 const auto& source_order=c.state().facts.order();const auto accepted=std::find(source_order.begin(),source_order.end(),t.start_fact_ref.id);
 auto before=[&](const StableId& id){const auto at=std::find(source_order.begin(),source_order.end(),id);if(at==source_order.end())fail("ExactNavalRepairOriginalHeaderRequired",id);return at<accepted;};
 for(const auto& row:s.naval_repair_time_sources.rows()){const auto& other=row.second;if(other.timing.action_ref!=t.action_ref&&other.original_terms.fleet_id==terms.fleet_id&&before(other.timing.start_fact_ref.id)&&(!other.timing.result_ref||!before(other.timing.result_ref->id)))fail("NavalRepairHistoryOccupationOverlap",t.action_ref);}
 for(const auto& other:n.repairs.starts)if(other.terms.fleet_id==terms.fleet_id&&before(other.id)){const NavalRepairResult* result=nullptr;for(const auto& r:n.repairs.results)if(r.action_id==other.id)result=&r;if(!result||!before(result->id))fail("NavalRepairHistoryOccupationOverlap",t.action_ref);}
 const NavalRepairRule* rule=nullptr;for(const auto& r:x.naval_catalog.repair_policy->rules)if(r.id==terms.rule_id)rule=&r;
 if(!rule||terms.duration!=rule->duration||terms.materials!=rule->materials||terms.actor_id.empty()||terms.fleet_id.empty()||terms.army_id.empty()||terms.vessel_id.empty()||terms.unit_id.empty()||terms.captain_actor_id.empty()||terms.formation_source_id.empty()||terms.command_source_id.empty()||terms.inventory_id.empty()||terms.owner.kind!=Owner::Kind::organization||terms.owner.id.empty()||terms.owner.extra||terms.integrity_before<0||terms.integrity_after<=terms.integrity_before)fail("ExactNavalRepairOriginalTermsMismatch",t.action_ref);
 const NavalHullDefinition* hull=nullptr;for(const auto& h:x.naval_catalog.hulls)if(h.id==rule->hull_id)hull=&h;
 if(!hull)fail("ExactNavalRepairOriginalHullRequired",t.action_ref);
 Integer limit=hull->max_integrity;if(std::holds_alternative<WildernessLocation>(terms.anchor))limit=rule->afloat_integrity_limit;else if(!std::holds_alternative<SettlementLocation>(terms.anchor))fail("NavalRepairAnchorRequired",t.action_ref);
 if(terms.integrity_before>=limit||terms.integrity_after!=terms.integrity_before+std::min(rule->integrity_gain,limit-terms.integrity_before)||Integer(terms.crew_ids.size())<rule->minimum_crew)fail("ExactNavalRepairOriginalRuleMismatch",t.action_ref);
 std::set<StableId> participants,crew;for(const auto& id:terms.participants)if(id.empty()||!participants.insert(id).second)fail("NavalRepairParticipantsRequired",t.action_ref);
 if(!participants.count(terms.actor_id)||!participants.count(terms.captain_actor_id))fail("NavalRepairParticipantsRequired",t.action_ref);
 for(const auto& id:terms.crew_ids)if(id.empty()||!crew.insert(id).second)fail("NavalRepairCrewUnavailable",t.action_ref);
 const auto* berth=std::get_if<SettlementLocation>(&terms.anchor);
 if(bool(f.original_charge)!=(bool(x.naval_catalog.repair_charge_policy)&&bool(berth)))fail("ExactNavalRepairChargeCoverageMismatch",t.action_ref);
 if(f.original_charge){const auto& charge=*f.original_charge;if(!x.naval_catalog.repair_charge_policy||charge.action_id!=t.action_ref||t.charge_source_refs.size()!=1||!same_source(t.charge_source_refs.front(),charge_ref(t.action_ref))||charge.terms.rule_id!=terms.rule_id||charge.terms.army_id!=terms.army_id||!owner_equal(charge.terms.payer_owner,terms.owner)||charge.terms.amount<1||charge.terms.payer_wallet_id==charge.terms.payee_wallet_id)fail("ExactNavalRepairChargeBindingMismatch",t.action_ref);
  const NavalRepairService* service=nullptr;for(const auto& actual:x.naval_catalog.repair_charge_policy->services)if(actual.id==charge.terms.service_id)service=&actual;
  const auto& q=charge.terms;if(!service||!berth||q.service_version!=service->version||q.rule_id!=service->rule_id||q.berth_place_id!=service->berth_place_id||q.berth_place_id!=berth->place_id||q.garrison_id!=service->garrison_id||q.payee_wallet_id!=service->wallet_id||q.amount!=service->fee||q.payee_owner.kind!=Owner::Kind::organization||q.payee_owner.id!=service->organization_id||q.payee_owner.extra)fail("ExactNavalRepairChargeOriginalServiceMismatch",t.action_ref);
 }
 else if(!t.charge_source_refs.empty())fail("ExactNavalRepairChargePayloadRequired",t.action_ref);
 if(f.original_result){const auto& r=*f.original_result;if(!t.completion_or_interruption_at||!t.result_ref||!same_source(*t.result_ref,result_ref(r.id))||!allocated(r.id,"naval_repair:")||r.action_id!=t.action_ref||r.actor_id!=terms.actor_id||take(compare_world_moments(*t.completion_or_interruption_at,t.started_at,x.budget))<0||take(compare_world_moments(*t.completion_or_interruption_at,due(f,x.budget),x.budget))>0)fail("ExactNavalRepairResultIdentityMismatch",r.id);header(c,*t.result_ref);
  const auto& order=c.state().facts.order();const auto begin=std::find(order.begin(),order.end(),t.start_fact_ref.id),end=std::find(order.begin(),order.end(),t.result_ref->id);if(begin==order.end()||end==order.end()||begin>=end||take(compare_world_moments(*t.completion_or_interruption_at,now,x.budget))>0)fail("ExactNavalRepairResultCausalOrderMismatch",r.id);
  if(r.reason=="NavalRepairCompleted"){if(!r.success||!r.request_key.empty()||!r.interruption_source_id.empty()||r.actual_interruption_source||!same_moment(*t.completion_or_interruption_at,due(f,x.budget),x.budget))fail("ExactNavalRepairCompletedResultMismatch",r.id);}
  else if(r.reason=="NavalRepairCancelled"){if(r.success||!naval_request_key_valid(r.request_key)||!r.interruption_source_id.empty()||r.actual_interruption_source)fail("ExactNavalRepairCancellationMismatch",r.id);}
  else if(r.reason=="NavalRepairContact"||r.reason=="NavalRepairCrewChanged"||r.reason=="NavalRepairServiceChanged"){
   if(r.success||!r.request_key.empty()||!r.actual_interruption_source||r.actual_interruption_source->source_schema<1||r.actual_interruption_source->source_ref.id.empty()||same_source(r.actual_interruption_source->source_ref,*t.result_ref)||same_source(r.actual_interruption_source->source_ref,t.start_fact_ref))fail("ExactNavalRepairActualInterruptionRequired",r.id);
   if(r.reason=="NavalRepairCrewChanged"){if(!r.interruption_source_id.empty())fail("ExactNavalRepairOriginalInterruptionMismatch",r.id);}
   else if(r.interruption_source_id!=r.actual_interruption_source->source_ref.id||(r.reason=="NavalRepairServiceChanged"&&!f.original_charge))fail("ExactNavalRepairOriginalInterruptionMismatch",r.id);
  }else fail("InvalidExactNavalRepairResultReason",r.id);
 }else if(t.completion_or_interruption_at||t.result_ref)fail("ExactNavalRepairResultPayloadRequired",t.action_ref);
}
void validate_shape(const CommonStore& c,const MilitaryState& m,const NavalState& n,const MilitaryActionTimeState& s,const ExactNavalRepairReadContext& x,const NewNavalRepairTimeSource2& f){
 bound(c,m,n,s,x);validate_source_shape(c,n,s,{x.military_catalog,x.access,x.naval_catalog,x.scale,x.clock,x.budget},f);take(x.original.validate_naval_repair_acceptance(f));
}
Status validate_current_escrow(const CommonStore& c,const NavalState& n,const NewNavalRepairTimeSource2& f){return status([&]{const auto& t=f.original_terms;const auto& id=f.timing.action_ref;
 const auto* action=c.action(id);if(!action||action->kind!="naval_repair"||action->actor_id!=t.actor_id||action->participants!=t.participants||action->start_tick!=f.timing.started_at.half_day_tick)fail("ExactNavalRepairActualActionRequired",id);
 for(const auto& person:t.participants){const auto* actor=c.actor(person);if(!actor||actor->action_id!=id)fail("NavalRepairOccupationMissing",person);}
 const NavalVesselRecord* vessel=nullptr;for(const auto& v:n.vessels)if(v.id==t.vessel_id)vessel=&v;if(!vessel||vessel->integrity!=t.integrity_before)fail("NavalRepairHullPredecessorMismatch",id);
 const auto* inventory=c.inventory(t.inventory_id);if(!inventory||!owner_equal(inventory->owner,t.owner))fail("NavalRepairMaterialAuthorityRequired",id);
 // Exact escrow additionally forbids any wrong Owner or empty reserved lot.
 // These are whole-contract qualification checks; the quantity calculation is
 // the same original Common count used by hot acceptance and resource apply.
 for(const auto& material:t.materials){for(const auto& lot:inventory->lots)if(lot.reserved_by==ReservationRef{id}&&lot.item_id==material.first)if(!owner_equal(lot.owner,t.owner)||lot.quantity<1)fail("NavalRepairMaterialOverflow",id);auto quantity=count_inventory_items(c,inventory->id,material.first,{t.owner},ReservationRef{id});if(!quantity.ok&&quantity.error.original.code=="ProjectionOverflow")fail("NavalRepairMaterialOverflow",id);if(take(quantity)!=material.second)fail("NavalRepairMaterialsRequired",material.first);}
 for(const auto& row:c.state().inventories.rows())for(const auto& lot:row.second.lots)if(lot.reserved_by==ReservationRef{id}){bool valid=false;for(const auto& material:t.materials)if(row.first==t.inventory_id&&lot.item_id==material.first&&owner_equal(lot.owner,t.owner))valid=true;if(!valid)fail("ExactNavalRepairUnexpectedMaterialReservation",id);}
 std::size_t wallet_count=0;for(const auto& row:c.state().wallets.rows())for(const auto& r:row.second.reserved)if(r.action_id==ReservationRef{id}){++wallet_count;if(!f.original_charge||row.first!=f.original_charge->terms.payer_wallet_id||r.amount!=f.original_charge->terms.amount||!owner_equal(row.second.owner,f.original_charge->terms.payer_owner))fail("ExactNavalRepairChargeReservationMismatch",id);}
 if(wallet_count!=(f.original_charge?1u:0u))fail("ExactNavalRepairChargeReservationMismatch",id);
});}
Status validate_fact_history(const CommonStore& c,const MilitaryState& m,const NavalState& n,const MilitaryActionTimeState& s,const ExactNavalRepairReadContext& x,const NewNavalRepairTimeSource2& f,const ActionElapsedState& e,bool pending){return status([&]{
 validate_shape(c,m,n,s,x,f);const auto& t=f.timing;const auto now=take(x.clock.read_current_moment());
 if(e.action_ref!=t.action_ref||e.execution_source_ref!=t.action_ref||e.duration_definition_ref!="naval_repair_original_duration_v2"||e.owner_cost_state_ref!=t.action_ref||e.owner_work_remainder||!same_moment(e.started_at,t.started_at,x.budget)||compare(e.required_units.value,take(fixed_duration_work_units(f.original_terms.duration,x.scale.units_per_half_day,x.budget)).value,x.budget)||take(compare_world_moments(e.last_settled_at,t.started_at,x.budget))<0||take(compare_world_moments(e.last_settled_at,now,x.budget))>0)fail("ExactNavalRepairElapsedBindingMismatch",t.action_ref);
 const auto actual=take(duration_to_scale_units(take(elapsed_world_duration(t.started_at,e.last_settled_at,x.budget)),x.scale.units_per_half_day,x.budget));if(compare(actual.value,e.credited_units.value,x.budget)||compare(e.credited_units.value,e.required_units.value,x.budget)>0)fail("ExactNavalRepairActualServiceMismatch",t.action_ref);
 if(take(compare_world_moments(t.started_at,e.last_settled_at,x.budget))<0)take(x.original.validate_naval_repair_actual_service(f,{t.started_at,e.last_settled_at}));
 if(f.original_result){if(!same_moment(*t.completion_or_interruption_at,e.last_settled_at,x.budget)||(f.original_result->success&&compare(e.credited_units.value,e.required_units.value,x.budget)))fail("ExactNavalRepairTerminalServiceMismatch",t.action_ref);take(x.original.validate_naval_repair_completed_result(f));}
 else {const auto order=take(compare_world_moments(e.last_settled_at,due(f,x.budget),x.budget));if(order>0||(!pending&&order==0))fail("ExactNavalRepairUnconsumedCompletion",t.action_ref);}
});}
}
Status validate_exact_naval_repair_sources(const CommonStore& c,const MilitaryState& m,const NavalState& n,const MilitaryActionTimeState& s,const ActionElapsedStore& elapsed,const ExactNavalRepairReadContext& x,bool pending){return status([&]{
 bound(c,m,n,s,x);NativeNavalRepairActionTimeRead reader(c,m,n,s,elapsed,x);const auto reg=exact_naval_repair_action_registration();std::set<std::pair<StableId,StableId>> keys;std::set<StableId> results,active_fleets;
 for(const auto& old:n.repairs.starts)if(!keys.emplace(old.terms.actor_id,old.request_key).second)fail("NavalIdempotencyConflict",old.request_key);for(const auto& old:n.repairs.results)if(!old.request_key.empty()&&!keys.emplace(old.actor_id,old.request_key).second)fail("NavalIdempotencyConflict",old.request_key);
 for(const auto& row:s.naval_repair_time_sources.rows()){const auto& f=row.second;const auto& id=f.timing.action_ref;if(row.first!=id||!keys.emplace(f.original_terms.actor_id,f.request_key).second)fail("ExactNavalRepairSourceKeyMismatch",id);const auto* e=find_fixed_elapsed(elapsed,id);if(!e)fail("ExactNavalRepairElapsedRequired",id);take(validate_fact_history(c,m,n,s,x,f,*e,pending));
  if(f.original_result){const auto& r=*f.original_result;if(!results.insert(r.id).second||(!r.request_key.empty()&&!keys.emplace(r.actor_id,r.request_key).second))fail("NavalIdempotencyConflict",r.id);}
  if(pending&&!f.original_result)take(read_fixed_service_intervals_at_completion_due(elapsed,id,f.timing.started_at,e->last_settled_at,take(x.clock.read_current_moment()),x.scale,x.budget));else take(read_fixed_service_intervals(elapsed,id,f.timing.started_at,e->last_settled_at,take(x.clock.read_current_moment()),x.scale,x.budget));
  const auto proof=take(reader.read_action_time_owner(reg,id));std::vector<FixedServiceTransition> transitions;for(const auto& t:elapsed.fixed_service_transitions)if(t.action_ref==id)transitions.push_back(t);take(reader.validate_fixed_action_sources(reg,proof,*e,transitions));
  if(!f.original_result){if(!active_fleets.insert(f.original_terms.fleet_id).second||!std::holds_alternative<ElapsedRunning>(e->timing))fail("NavalRepairAlreadyActive",id);take(validate_current_escrow(c,n,f));const auto* a=c.action(id);if(!a||(!(pending&&compare(e->credited_units.value,e->required_units.value,x.budget)==0)&&a->remaining_ticks!=take(fixed_elapsed_remaining_ticks(*e,x.scale,x.budget))))fail("ExactNavalRepairActionProjectionMismatch",id);}
  else {if(c.action(id)||!std::holds_alternative<ElapsedTerminal>(e->timing))fail("ExactNavalRepairTerminalNotReleased",id);for(const auto& wallet:c.state().wallets.rows())for(const auto& r:wallet.second.reserved)if(r.action_id==ReservationRef{id})fail("ExactNavalRepairTerminalReservationRetained",id);for(const auto& inv:c.state().inventories.rows())for(const auto& lot:inv.second.lots)if(lot.reserved_by==ReservationRef{id})fail("ExactNavalRepairTerminalReservationRetained",id);}
 }
 for(const auto& row:c.state().facts.rows())if(row.second.domain=="military_naval"&&(row.second.kind=="naval_repair_start"||row.second.kind=="naval_repair_result")){bool found=false;if(row.second.kind=="naval_repair_start"){found=s.naval_repair_time_sources.find(row.first);for(const auto& old:n.repairs.starts)if(old.id==row.first)found=true;}else{found=results.count(row.first);for(const auto& old:n.repairs.results)if(old.id==row.first)found=true;}if(!found)fail("MissingNavalRepairOriginalPayload",row.first);}
 for(const auto& row:c.state().actions.rows())if(row.second.kind=="naval_repair"){bool legacy=false;for(const auto& old:n.repairs.starts)if(old.id==row.first)legacy=true;if(!s.naval_repair_time_sources.find(row.first))fail(legacy?"LegacyNavalRepairTimerCannotRunExactProfile":"MissingExactNavalRepairSource",row.first);}
});}
Outcome<const NewNavalRepairTimeSource2*> read_verified_exact_naval_repair_result(const CommonStore& c,const MilitaryState& m,const NavalState& n,const MilitaryActionTimeState& s,const ActionElapsedStore& elapsed,const ExactNavalRepairReadContext& x,const SourceRef& ref,Integer schema){return guard<const NewNavalRepairTimeSource2*>([&]{
 if(schema!=2||ref.domain!="military_naval"||ref.kind!="naval_repair_result")fail("ExactNavalRepairResultRequired",ref.id);const auto& f=result_fact(s,ref.id);const auto* e=find_fixed_elapsed(elapsed,f.timing.action_ref);if(!e)fail("ExactNavalRepairElapsedRequired",f.timing.action_ref);take(validate_fact_history(c,m,n,s,x,f,*e,false));take(read_fixed_service_intervals(elapsed,f.timing.action_ref,f.timing.started_at,*f.timing.completion_or_interruption_at,take(x.clock.read_current_moment()),x.scale,x.budget));NativeNavalRepairActionTimeRead reader(c,m,n,s,elapsed,x);const auto reg=exact_naval_repair_action_registration();const auto proof=take(reader.read_action_time_owner(reg,f.timing.action_ref));std::vector<FixedServiceTransition> transitions;for(const auto& t:elapsed.fixed_service_transitions)if(t.action_ref==f.timing.action_ref)transitions.push_back(t);take(reader.validate_fixed_action_sources(reg,proof,*e,transitions));if(c.action(f.timing.action_ref)||!std::holds_alternative<ElapsedTerminal>(e->timing))fail("ExactNavalRepairTerminalNotReleased",f.timing.action_ref);return &f;
});}
Outcome<ExactNavalRepairSourceView> read_verified_exact_naval_repair_source(const CommonStore& c,const MilitaryState& m,const NavalState& n,const MilitaryActionTimeState& s,const ActionElapsedStore& elapsed,const ExactNavalRepairReadContext& x,const SourceRef& ref,Integer schema){return guard<ExactNavalRepairSourceView>([&]{
 if(schema!=2||ref.domain!="military_naval")fail("ExactNavalRepairSourceRequired",ref.id);
 if(ref.kind=="naval_repair_result"){const auto* f=take(read_verified_exact_naval_repair_result(c,m,n,s,elapsed,x,ref,schema));return ExactNavalRepairSourceView{f,*f->timing.completion_or_interruption_at};}
 if(ref.kind!="naval_repair_start"&&ref.kind!="naval_repair_charge")fail("ExactNavalRepairSourceRequired",ref.id);
 const auto& f=fact(s,ref.id);if(ref.kind=="naval_repair_charge"&&!f.original_charge)fail("ExactNavalRepairChargePayloadRequired",ref.id);const auto* e=find_fixed_elapsed(elapsed,f.timing.action_ref);if(!e)fail("ExactNavalRepairElapsedRequired",ref.id);take(validate_fact_history(c,m,n,s,x,f,*e,false));take(read_fixed_service_intervals(elapsed,f.timing.action_ref,f.timing.started_at,e->last_settled_at,take(x.clock.read_current_moment()),x.scale,x.budget));
 NativeNavalRepairActionTimeRead reader(c,m,n,s,elapsed,x);const auto reg=exact_naval_repair_action_registration();auto proof=take(reader.read_action_time_owner(reg,f.timing.action_ref));std::vector<FixedServiceTransition> transitions;for(const auto& row:elapsed.fixed_service_transitions)if(row.action_ref==f.timing.action_ref)transitions.push_back(row);take(reader.validate_fixed_action_sources(reg,proof,*e,transitions));return ExactNavalRepairSourceView{&f,f.timing.started_at};
});}

}
